"H7":[{"t":"海报《战争开始了》","d":"1967年6月7日","ty":"文献影像","src":"King’s College London — Mao Era in Objects · Fei Yiming (Ta Kung Pao). Fair use.","url":"https://mao-static.kdl.kcl.ac.uk/sources/big-character-poster-hong-kong-ta-kung-pao-article/index.html","f":"kcl-19f71253e3b760.jpg","w":668,"h":1000,"tr":[28,2,104,156]},{"t":"流通卡","d":"1959年10月","ty":"文献影像","src":"King’s College London — Mao Era in Objects · Personal Collection. Fair use.","url":"https://mao-static.kdl.kcl.ac.uk/sources/borrowed-books-circulation-card-2/index.html","f":"kcl-b77e74f2a05bc1.jpg","w":800,"h":723,"tr":[162,9,156,141]},{"t":"流通卡","d":"1959年10月","ty":"文献影像","src":"King’s College London — Mao Era in Objects · Personal Collection. Fair use.","url":"https://mao-static.kdl.kcl.ac.uk/sources/borrowed-books-circulation-card-1/index.html","f":"kcl-d45e04feaa6b6c.jpg","w":535,"h":1000,"tr":[358,2,83,156]},{"t":"调动一切积极因素正确处理人民内部矛盾","d":"1958年6月","ty":"宣传画（印刷品扫描）","src":"Chinese Posters · Landsberger collection","url":"https://chineseposters.net/posters/e13-990","f":"cp-e13-990.jpg","w":402,"h":580,"desc":"此书为毛泽东《关于正确处理人民内部矛盾的问题》，1957年首次出版。","en":"The book is Mao's On the Correct Handling of Contradictions among the People (关于正确处理人民内部矛盾的问题, Guanyu zhengque chuli renmin neibu maodun de wenti), first published in 1957.","tr":[506,2,108,156]},{"t":"乘风破浪的“和平28号”","d":"1958年9月","ty":"宣传画（印刷品扫描）","src":"Chinese Posters · Private collection","url":"https://chineseposters.net/posters/pc-1958-016","f":"cp-pc-1958-016.jpg","w":580,"h":402,"desc":"沿海散货船“和平28号”于1958年在上海江南造船厂建造，据称仅用70天完成。这被作为工人阶级在反右运动后的一项胜利。","en":"The coastal bulk carrier Peace 28 (和平28 - Heping 28) was constructed at the Shanghai Jiangnan Shipyard (上海江南造船厂) in 1958, allegedly in just 70 days. This was presented as a triumph of the working class just after the campaign against the \"rightists'.","tr":[642,26,156,108]}],
